head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vParentScrenID = "";
scwin.vScrenTpCD = "";
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용
scwin.getPar, scwin.setPar;
scwin.Isur_cd = "", scwin.Isur_nm = "", scwin.Secugrp_id = "", scwin.Mkt_id = "", scwin.fr_bz_procs_no = "";
scwin.vBzProcsNo;
scwin.vSecugrpID;
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        const fnc = $c.frame.path("../").scwin.getPar;
        const arrPar = new Array();
        fnc(arrPar); // Provider callback
        scwin.Isur_cd = (arrPar.length >= 1 ? arrPar[0] : "");
        scwin.Isur_nm = (arrPar.length >= 2 ? arrPar[1] : "");
        scwin.Secugrp_id = (arrPar.length >= 3 ? arrPar[2] : "");
        scwin.Mkt_id = (arrPar.length >= 4 ? arrPar[3] : "");
        scwin.fr_bz_procs_no = (arrPar.length >= 5 ? arrPar[4] : "");
        const parentWin = $c.frame.path("../");
        scwin.vSecugrpID = parentWin.scwin.vSecugrpID;
        scwin.vParentScrenID = parentWin.scwin.vScrenID;

        /* buttonSet Event*/
        buttonSet.setSaveInfo(btn_Save, scwin.save);
        buttonSet.setUpdateInfo(btn_Update, scwin.update);
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete);
        buttonSet.setDsclInfo(btn_Dscl, scwin.dscl);
        const sbmOptions = {
            id : "sbm_dts_FiscyyChg",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_FiscyyChg=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        dts_FiscyyChg.insertRow();
        const vCurDate = $c.ut.cGetToday("yyyymmdd"); // Modify Date
        edt_MKTACT_ENFORCE_DD.setValue(scwin.vCurDate);
        img_MKTACT_ENFORCE_DD.hide();
        if (scwin.Isur_cd !== "") {
            // Modify Mode
            txb_ISUR_CD.setValue(scwin.Isur_cd);
            txb_COM_NM.setValue(scwin.Isur_nm);
            img_COM_NM.hide();
            buttonSet.setUpdateStatus();
            await scwin.readSync();
        } else {
            // Insert  Mode
            img_COM_NM.show("");
            buttonSet.setInsertStatus();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05629.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
