/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');

        // ReFresh
        await scwin.readSync();

        // Parent ReFresh
        scwin.parentRefresh();
        buttonSet.setUpdateStatus();
        img_COM_NM.hide();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05629.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Delete_OnSuccess
 * @description Delete On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Delete_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        scwin.parentRefresh();
        // buttonSet.setInsertStatus();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05629.trs_Delete_OnSuccess" });
    }
};

