///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name readSync
 * @description read Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSync = async function() {
    url += "?SCREN_ID=" + "ULDSTF05628.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=exstreadMarket&inputMessageId=FISCYY_CHG_INOUT" + "&BZ_PROCS_NO=" + scwin.fr_bz_procs_no;
    const sbmOptions = {
        id : "sbm_dts_FiscyyChg",
        action : "/fiscalYearChange.do",
        ref : "",
        target : "dts_FiscyyChg=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name getBfChgAcntclsReadSync
 * @description get Bf Chg Acntcls Read Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getBfChgAcntclsReadSync = async function() {
    url += "?SCREN_ID=" + "ULDSTF05628.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=getBfChgExstStrtDd&inputMessageId=BFCHG_ACNTCLS_OUT" + "&ISUR_CD=" + txb_ISUR_CD.getValue();
    const sbmOptions = {
        id : "sbm_dts_BfChgAcntcls",
        action : "/fiscalYearChange.do",
        ref : "",
        target : "dts_BfChgAcntcls=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name checkInsertable
 * @description check Insertable 처리
 * @param {String} IsurCd IsurCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkInsertable = async function(IsurCd) {
    url += "?SCREN_ID=" + "ULDSTF05628.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01; //  01 List
    url += "&method=exstlistMarket&inputMessageId=FISCYY_CHG_INOUT&ISUR_CD=" + IsurCd;
    url += "&STYPE=1";
    url += "&BZ_SDATE=";
    url += "&BZ_EDATE=";
    url += "&BF_EXST_MODIFY_YN=";
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/fiscalYearChange.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const rowCnt = dts_List.getRowCount();
    if (rowCnt === 0) {
        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name save
 * @description Check Insertable
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    // Check Insertable
    if (!await scwin.checkInsertable(txb_ISUR_CD.getValue())) {
        await $c.win.alert(txb_ISUR_CD.getValue() + " " + txb_COM_NM.getValue() + " 회사코드(명)이  존립기간 관리에 이미 존재합니다.");
        return;
    }
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess('I')) // Message Box
            return;
        scwin.vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
        scwin.fr_bz_procs_no = scwin.vBzProcsNo;
        if (scwin.vBzProcsNo.length !== 14) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            //
            // ********************************************************************

            scwin.Isur_cd = txb_ISUR_CD.getValue(); /*ORG SRC: dts_FiscyyChg.UserStatus(1) = TB_JOB_INSERT;*/ X = TB_JOB_INSERT;
            dts_FiscyyChg.setCellData(1, "ISUR_CD", scwin.Isur_cd); // 회사코드를 바인딩한다.
            dts_FiscyyChg.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
            url += "?SCREN_ID=" + "ULDSTF05628.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
            url += "&method=exstMarketDisclsCal&inputMessageId=FISCYY_CHG_INOUT";
            url += "&AFCHG_EXST_END_DD=" + edt_Mktact_afchgexst_end_Dd.getValue();
            const sbmOptions = {
                id : "sbm_dts_BzDisclsCal",
                action : "/fiscalYearChange.do",
                ref : "",
                target : "dts_BzDisclsCal=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

            dts_FiscyyChg.setCellData(1, "ADMISUNOTI_DD", dts_BzDisclsCal.getCellData(1, "ADMISUNOTI_DD"));
            dts_FiscyyChg.setCellData(1, "ADMISU_DISCLS_DD", dts_BzDisclsCal.getCellData(1, "ADMISU_DISCLS_DD"));
            dts_FiscyyChg.setCellData(1, "ADMISU_DESIGN_DD", dts_BzDisclsCal.getCellData(1, "ADMISU_DESIGN_DD"));
            dts_FiscyyChg.setCellData(1, "DELIST_ADVNOTI_DD", dts_BzDisclsCal.getCellData(1, "DELIST_ADVNOTI_DD"));
            dts_FiscyyChg.setCellData(1, "DELIST_DISCLS_DD", dts_BzDisclsCal.getCellData(1, "DELIST_DISCLS_DD"));
            dts_FiscyyChg.setCellData(1, "DELIST_DD", dts_BzDisclsCal.getCellData(1, "DELIST_DD"));
            await scwin.trs();
        }
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess('U')) // Message Box

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            //
            // ********************************************************************

            return; /*ORG SRC: dts_FiscyyChg.UserStatus(1) = TB_JOB_UPDATE;*/ X = TB_JOB_UPDATE;
        dts_FiscyyChg.setCellData(1, "ISUR_CD", scwin.Isur_cd);
        dts_FiscyyChg.setCellData(1, "BZ_PROCS_NO", scwin.fr_bz_procs_no);
        url += "?SCREN_ID=" + "ULDSTF05628.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=exstMarketDisclsCal&inputMessageId=FISCYY_CHG_INOUT";
        url += "&AFCHG_EXST_END_DD=" + edt_Mktact_afchgexst_end_Dd.getValue();
        const sbmOptions = {
            id : "sbm_dts_BzDisclsCal",
            action : "/fiscalYearChange.do",
            ref : "",
            target : "dts_BzDisclsCal=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        dts_FiscyyChg.setCellData(1, "ADMISUNOTI_DD", dts_BzDisclsCal.getCellData(1, "ADMISUNOTI_DD"));
        dts_FiscyyChg.setCellData(1, "ADMISU_DISCLS_DD", dts_BzDisclsCal.getCellData(1, "ADMISU_DISCLS_DD"));
        dts_FiscyyChg.setCellData(1, "ADMISU_DESIGN_DD", dts_BzDisclsCal.getCellData(1, "ADMISU_DESIGN_DD"));
        dts_FiscyyChg.setCellData(1, "DELIST_ADVNOTI_DD", dts_BzDisclsCal.getCellData(1, "DELIST_ADVNOTI_DD"));
        dts_FiscyyChg.setCellData(1, "DELIST_DISCLS_DD", dts_BzDisclsCal.getCellData(1, "DELIST_DISCLS_DD"));
        dts_FiscyyChg.setCellData(1, "DELIST_DD", dts_BzDisclsCal.getCellData(1, "DELIST_DD"));
        await scwin.trs();
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    if (!$c.lc.fn_isProcess('D')) // Message Box

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        //
        // ********************************************************************

        return; /*ORG SRC: dts_FiscyyChg.UserStatus(1) = TB_JOB_DELETE;*/ X = TB_JOB_DELETE;
    scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
    dts_FiscyyChg.setCellData(1, "ISUR_CD", scwin.Isur_cd);
    dts_FiscyyChg.setCellData(1, "BZ_PROCS_NO", scwin.fr_bz_procs_no);
    trs_Delete.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_Delete",
        action : "/fiscalYearChange.do",
        ref : "dts_FiscyyChg",
        target : "trs_Delete=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name trs
 * @description trs 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function() {
    if (dts_FiscyyChg.UserStatus(1) === '1') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (dts_FiscyyChg.UserStatus(1) === '3') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    }
    trs_Save.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/fiscalYearChange.do",
        ref : "dts_FiscyyChg",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

